/**
 * Subgroup pointwise convolution prototype: a 32x128 output tile, eight rows
 * per subgroup and four spatial elements per lane. No workgroup scratch/barriers.
 * Uses reported subgroup IDs/sizes; it does not infer lane layout from local IDs.
 * Source: https://github.com/barhanc/wgpu-executorch
 * License: MIT (Copyright (c) 2026 Bartosz Hanc <bartosz.hanc02@gmail.com>)
 */
export const SHADER_CONV2D_1X1_SUBGROUP_F16 = /* wgsl */ `
requires subgroup_id;
enable subgroups;
enable f16;

@group(0) @binding(0) var<storage, read_write> out: array<vec4<f16>>;
@group(0) @binding(1) var<storage, read> input: array<vec4<f16>>;
@group(0) @binding(2) var<storage, read> weight: array<vec4<f16>>;
@group(0) @binding(3) var<storage, read> bias: array<f16>;

struct Params {
  B: u32, IC: u32, IH: u32, IW: u32,
  OC: u32, OH: u32, OW: u32, KH: u32, KW: u32,
  sH: u32, sW: u32, pH: u32, pW: u32, dH: u32, dW: u32,
  groups: u32, has_bias: u32, _p0: u32, _p1: u32, _p2: u32,
}
@group(0) @binding(4) var<uniform> params: Params;


@compute @workgroup_size(128)
fn main(
  @builtin(workgroup_id) group: vec3<u32>,
  @builtin(subgroup_id) subgroup: u32,
  @builtin(num_subgroups) subgroup_count: u32,
  @builtin(subgroup_invocation_id) lane: u32,
  @builtin(subgroup_size) lanes: u32,
) {
  let M = params.OC;
  let N_vecs = (params.OH * params.OW) >> 2u;
  let K_vecs = params.IC >> 2u;
  let k_groups = ((params.IC + 15u) >> 4u) * 4u;
  for (var row_block = 0u; row_block < 32u; row_block += subgroup_count * 8u) {
    let row_relative = row_block + subgroup * 8u;
    let row_base = group.y * 32u + row_relative;
    for (var col_block = 0u; col_block < 32u; col_block += lanes) {
      let col = group.x * 32u + col_block + lane;
      let valid_col = col_block + lane < 32u && col < N_vecs;
      var acc0 = vec4<f16>(0.0h);
      var acc1 = vec4<f16>(0.0h);
      var acc2 = vec4<f16>(0.0h);
      var acc3 = vec4<f16>(0.0h);
      var acc4 = vec4<f16>(0.0h);
      var acc5 = vec4<f16>(0.0h);
      var acc6 = vec4<f16>(0.0h);
      var acc7 = vec4<f16>(0.0h);
      for (var k4 = 0u; k4 < k_groups; k4++) {
        var weight0 = vec4<f16>(0.0h);
        var weight1 = vec4<f16>(0.0h);
        if (lane < 4u && k4 < K_vecs) {
          if (row_relative + lane < 32u && row_base + lane < M) {
            weight0 = weight[(row_base + lane) * K_vecs + k4];
          }
          if (row_relative + lane + 4u < 32u && row_base + lane + 4u < M) {
            weight1 = weight[(row_base + lane + 4u) * K_vecs + k4];
          }
        }
        let a0 = subgroupBroadcast(weight0, 0u);
        let a1 = subgroupBroadcast(weight0, 1u);
        let a2 = subgroupBroadcast(weight0, 2u);
        let a3 = subgroupBroadcast(weight0, 3u);
        let a4 = subgroupBroadcast(weight1, 0u);
        let a5 = subgroupBroadcast(weight1, 1u);
        let a6 = subgroupBroadcast(weight1, 2u);
        let a7 = subgroupBroadcast(weight1, 3u);
        var b0 = vec4<f16>(0.0h);
        var b1 = vec4<f16>(0.0h);
        var b2 = vec4<f16>(0.0h);
        var b3 = vec4<f16>(0.0h);
        if (valid_col && k4 < K_vecs) {
          b0 = input[(k4 * 4u + 0u) * N_vecs + col];
          b1 = input[(k4 * 4u + 1u) * N_vecs + col];
          b2 = input[(k4 * 4u + 2u) * N_vecs + col];
          b3 = input[(k4 * 4u + 3u) * N_vecs + col];
        }
        acc0 = acc0 + b0 * a0.x + b1 * a0.y + b2 * a0.z + b3 * a0.w;
        acc1 = acc1 + b0 * a1.x + b1 * a1.y + b2 * a1.z + b3 * a1.w;
        acc2 = acc2 + b0 * a2.x + b1 * a2.y + b2 * a2.z + b3 * a2.w;
        acc3 = acc3 + b0 * a3.x + b1 * a3.y + b2 * a3.z + b3 * a3.w;
        acc4 = acc4 + b0 * a4.x + b1 * a4.y + b2 * a4.z + b3 * a4.w;
        acc5 = acc5 + b0 * a5.x + b1 * a5.y + b2 * a5.z + b3 * a5.w;
        acc6 = acc6 + b0 * a6.x + b1 * a6.y + b2 * a6.z + b3 * a6.w;
        acc7 = acc7 + b0 * a7.x + b1 * a7.y + b2 * a7.z + b3 * a7.w;
      }
      if (valid_col) {
        if (row_relative + 0u < 32u && row_base + 0u < M) {
          var value = acc0;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 0u]); }
          out[(row_base + 0u) * N_vecs + col] = value;
        }
        if (row_relative + 1u < 32u && row_base + 1u < M) {
          var value = acc1;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 1u]); }
          out[(row_base + 1u) * N_vecs + col] = value;
        }
        if (row_relative + 2u < 32u && row_base + 2u < M) {
          var value = acc2;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 2u]); }
          out[(row_base + 2u) * N_vecs + col] = value;
        }
        if (row_relative + 3u < 32u && row_base + 3u < M) {
          var value = acc3;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 3u]); }
          out[(row_base + 3u) * N_vecs + col] = value;
        }
        if (row_relative + 4u < 32u && row_base + 4u < M) {
          var value = acc4;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 4u]); }
          out[(row_base + 4u) * N_vecs + col] = value;
        }
        if (row_relative + 5u < 32u && row_base + 5u < M) {
          var value = acc5;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 5u]); }
          out[(row_base + 5u) * N_vecs + col] = value;
        }
        if (row_relative + 6u < 32u && row_base + 6u < M) {
          var value = acc6;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 6u]); }
          out[(row_base + 6u) * N_vecs + col] = value;
        }
        if (row_relative + 7u < 32u && row_base + 7u < M) {
          var value = acc7;
          if (params.has_bias != 0u) { value += vec4<f16>(bias[row_base + 7u]); }
          out[(row_base + 7u) * N_vecs + col] = value;
        }
      }
    }
  }
}
`;

