  var acc2 = vec4<f32>(0.0);
  var acc3 = vec4<f32>(0.0);

  // Load coordinates for 256 threads (each thread loads 1 vec4 of A/weight and 1 vec4 of B/input)
  let rows_per_subgroup = lanes >> 2u;
  let subgroup_row = subgroup * rows_per_subgroup;
  let weight_row = tile_row0 + subgroup_row + lane;
  let weight_lane_valid = lane < rows_per_subgroup && weight_row < M;

  let b_r = tid >> 4u;      // 0..15
  let b_c = tid & 15u;      // 0..15
  let b_n4 = tile_col0_4 + b_c;
  let b_c_valid = b_n4 < N_vecs;

  let num_tiles = (K + 15u) >> 4u;
  for (var t: u32 = 0u; t < num_tiles; t = t + 1u) {
    let k4_start = t << 2u;
    let k_start = t << 4u;

    let bk = k_start + b_r;
    if (bk < K && b_c_valid) {
      b_sub[b_r][b_c] = input[bk * N_vecs + b_n4];
    } else {
      b_sub[b_r][b_c] = vec4<f32>(0.0);
    }
    workgroupBarrier();

    let thread_r = subgroup_row + ((lane >> 4u) << 2u); // 0..60 (step 4)
    let thread_c4 = lane & 15u;      // 0..15

    for (var k4: u32 = 0u; k4 < 4u; k4 = k4 + 1u) {
      let b0 = b_sub[k4 * 4u + 0u][thread_c4];
      let b1 = b_sub[k4 * 4u + 1u][thread_c4];
      let b2 = b_sub[k4 * 4u + 2u][thread_c4];
      let b3 = b_sub[k4 * 4u + 3u][thread_c4];

      var weight_value = vec4<f32>(0.0);
      if (weight_lane_valid && k4_start + k4 < K_vecs) {
        weight_value = weight[weight_row * K_vecs + k4_start + k4];
      }
      let source_row = (lane >> 4u) << 2u;
      let a0 = subgroupShuffle(weight_value, source_row + 0u);
      let a1 = subgroupShuffle(weight_value, source_row + 1u);
      let a2 = subgroupShuffle(weight_value, source_row + 2u);
      let a3 = subgroupShuffle(weight_value, source_row + 3u);

      acc0 = acc0 + b0 * a0.x + b1 * a0.y + b2 * a0.z + b3 * a0.w;
      acc1 = acc1 + b0 * a1.x + b1 * a1.y + b2 * a1.z + b3 * a1.w;
      acc2 = acc2 + b0 * a2.x + b1 * a2.y + b2 * a2.z + b3 * a2.w;
      acc3 = acc3 + b0 * a3.x + b1 * a3.y + b2 * a3.z + b3 * a3.w;
    }
    workgroupBarrier();
  }

  let thread_r = subgroup_row + ((lane >> 4u) << 2u);
  let out_r0 = tile_row0 + thread_r;
  let out_c4 = tile_col0_4 + (lane & 15u);

  if (out_c4 < N_vecs) {
    if (out_r0 + 0u < M) {
      var v0 = acc0;
      if (params.has_bias != 0u) { v0 = v0 + vec4<f32>(bias[out_r0 + 0u]); }
      out[(out_r0 + 0u) * N_vecs + out_c4] = v0;
    }
    if (out_r0 + 1u < M) {
      var v1 = acc1;
      if (params.has_bias != 0u) { v1 = v1 + vec4<f32>(bias[out_r0 + 1u]); }
      out[(out_r0 + 1u) * N_vecs + out_c4] = v1;
    }
    if (out_r0 + 2u < M) {
      var v2 = acc2;
      if (params.has_bias != 0u) { v2 = v2 + vec4<f32>(bias[out_r0 + 2u]); }
      out[(out_r0 + 2u) * N_vecs + out_c4] = v2;
    }
    if (out_r0 + 3u < M) {
      var v3 = acc3;
      if (params.has_bias != 0u) { v3 = v3 + vec4<f32>(bias[out_r0 + 3u]); }
      out[(out_r0 + 3u) * N_vecs + out_c4] = v3;
    }
  }
}
`;
